using System.Globalization;
using System.Text;
using Sharpy.TestInfrastructure.Integration;
using Sharpy.TestInfrastructure.Oracles;
using Xunit;
using Xunit.Abstractions;

namespace Sharpy.Compiler.Tests.Properties.Differential;

/// <summary>
/// The end-to-end class guard for division by zero (#2517): <c>/</c>, <c>/=</c>, <c>**</c> and <c>**=</c> raise
/// <c>ZeroDivisionError</c> wherever CPython does, through every lowering the checker records. The cells are
/// GENERATED by crossing axes in code — operator × left operand type × right operand type × zero spelling
/// (a literal the compiler sees as a constant, a negative-zero literal, a local variable holding zero) — and
/// non-zero controls ride beside them. Every cell becomes one
/// <c>try: print(id, &lt;expr&gt;) except ZeroDivisionError as e: print(id, "ZeroDivisionError", e)</c> statement of
/// ONE program, rendered once as Sharpy (typed literals <c>1L</c>, <c>1.0f</c>, <c>1m</c>) and once as Python
/// (<c>int</c>, <c>float</c>, <c>Decimal</c>), run under both, and compared line by line.
/// </summary>
/// <remarks>
/// <para>Generated out, each a different class: <c>decimal</c> under <c>**</c> (Sharpy's decimal power is a
/// <c>float</c>, CPython's <c>Decimal(0) ** -1</c> is <c>Infinity</c>); a non-zero integer base with a negative
/// exponent (the spec's truncating <c>int ** int</c> deviation); <c>decimal</c> mixed with a float type (refused,
/// SPY0222); an augmented store whose result type is not the target's (refused, SPY0220).</para>
/// <para>Values are chosen so every non-raising result prints the same text in both languages (<c>3 / 4</c> is
/// <c>0.75</c> as float, float32 and decimal). Skips when no python3 ≥ 3.12 answers, except under
/// <c>SHARPY_REQUIRE_PYTHON_ORACLE=1</c> (CI), which fails.</para>
/// </remarks>
public class ZeroDivisionDifferentialTests : IntegrationTestBase
{
    public ZeroDivisionDifferentialTests(ITestOutputHelper output) : base(output) => MuteCompilePath = true;

    private enum Kind { Int, Long, Float, Float32, Decimal }

    private enum Zero { Literal, NegativeLiteral, Variable, NonZero }

    private static readonly Kind[] Kinds = { Kind.Int, Kind.Long, Kind.Float, Kind.Float32, Kind.Decimal };

    private sealed record Cell(int Id, string Sharpy, string Python, string Label);

    private static bool IsFloat(Kind k) => k is Kind.Float or Kind.Float32;

    private static bool IsInteger(Kind k) => k is Kind.Int or Kind.Long;

    /// <summary>A numeric literal of kind <paramref name="k"/>: (Sharpy text, Python text).</summary>
    private static (string Sharpy, string Python) Lit(Kind k, int value)
    {
        var v = value.ToString(CultureInfo.InvariantCulture);
        return k switch
        {
            Kind.Int => (v, v),
            Kind.Long => (v + "L", v),
            Kind.Float => (v + ".0", v + ".0"),
            Kind.Float32 => (v + ".0f", v + ".0"),
            _ => (v + "m", "Decimal(" + v + ")"),
        };
    }

    private static string TypeName(Kind k) => k switch
    {
        Kind.Int => "int",
        Kind.Long => "int64",
        Kind.Float => "float",
        Kind.Float32 => "float32",
        _ => "decimal",
    };

    /// <summary>The zero spellings a kind has: a negative-zero literal only where it is a distinct value spelling.</summary>
    private static IEnumerable<Zero> Spellings(Kind k)
    {
        yield return Zero.Literal;
        if (!IsInteger(k))
            yield return Zero.NegativeLiteral;
        yield return Zero.Variable;
        yield return Zero.NonZero;
    }

    /// <summary>Statements that bind <c>z</c> (when needed) and the operand text for a spelling.</summary>
    private static (string SharpySetup, string PythonSetup, string Sharpy, string Python) Operand(Kind k, Zero zero, int nonZero)
    {
        var lit0 = Lit(k, 0);
        return zero switch
        {
            Zero.Literal => ("", "", lit0.Sharpy, lit0.Python),
            Zero.NegativeLiteral => ("", "", "(-" + lit0.Sharpy + ")", "(-" + lit0.Python + ")"),
            Zero.Variable => ("z: " + TypeName(k) + " = " + lit0.Sharpy, "z = " + lit0.Python, "z", "z"),
            _ => ("", "", Lit(k, nonZero).Sharpy, Lit(k, nonZero).Python),
        };
    }

    private static Kind DivisionResult(Kind l, Kind r)
    {
        if (l == Kind.Decimal || r == Kind.Decimal)
            return Kind.Decimal;
        if (l == Kind.Float || r == Kind.Float)
            return Kind.Float;
        if (l == Kind.Float32 || r == Kind.Float32)
            return Kind.Float32;
        return Kind.Float;
    }

    private static Kind? PowerResult(Kind l, Kind r)
    {
        if (l == Kind.Float || r == Kind.Float)
            return Kind.Float;
        if (l == Kind.Float32 || r == Kind.Float32)
            return Kind.Float32;
        return l == Kind.Long || r == Kind.Long ? Kind.Long : Kind.Int;
    }

    private static bool Mixable(Kind l, Kind r) =>
        !((l == Kind.Decimal && IsFloat(r)) || (r == Kind.Decimal && IsFloat(l)));

    private static List<Cell> GenerateCells()
    {
        var cells = new List<Cell>();

        void Add(string label, string sharpySetup, string pythonSetup, string sharpyStmt, string pythonStmt)
        {
            var id = cells.Count;
            cells.Add(new Cell(id, Wrap(id, sharpySetup, sharpyStmt, "e"), Wrap(id, pythonSetup, pythonStmt, "msg(e)"), label));
        }

        foreach (var l in Kinds)
        {
            foreach (var r in Kinds)
            {
                if (!Mixable(l, r))
                    continue;

                // `/`: 3 / divisor, every divisor spelling.
                foreach (var zero in Spellings(r))
                {
                    var (ss, ps, sd, pd) = Operand(r, zero, 4);
                    var three = Lit(l, 3);
                    Add($"{TypeName(l)} / {TypeName(r)} ({zero})", ss, ps,
                        "print(ID, " + three.Sharpy + " / " + sd + ")", "print(ID, " + three.Python + " / " + pd + ")");

                    // `/=`: only where the result type is the target's own type.
                    if (DivisionResult(l, r) == l)
                    {
                        Add($"{TypeName(l)} /= {TypeName(r)} ({zero})", Join(ss, "x: " + TypeName(l) + " = " + three.Sharpy),
                            Join(ps, "x = " + three.Python), "x /= " + sd + "\n        print(ID, x)", "x /= " + pd + "\n        print(ID, x)");
                    }
                }

                // `**`: a zero (or control 2) base raised to -1 and to 2; decimal is a different class.
                if (l == Kind.Decimal || r == Kind.Decimal)
                    continue;
                foreach (var zero in Spellings(l))
                {
                    var (ss, ps, sb, pb) = Operand(l, zero, 2);
                    foreach (var exponent in new[] { -1, 2 })
                    {
                        if (zero == Zero.NonZero && exponent < 0 && IsInteger(l) && IsInteger(r))
                            continue; // the truncating int ** negative deviation
                        var e = Lit(r, exponent);
                        Add($"{TypeName(l)} ** {TypeName(r)} {exponent} ({zero})", ss, ps,
                            "print(ID, " + sb + " ** " + e.Sharpy + ")", "print(ID, " + pb + " ** " + e.Python + ")");

                        // `**=`: only where the result type is the target's own type.
                        if (PowerResult(l, r) == l)
                        {
                            Add($"{TypeName(l)} **= {TypeName(r)} {exponent} ({zero})",
                                Join(ss, "x: " + TypeName(l) + " = " + sb), Join(ps, "x = " + pb),
                                "x **= " + e.Sharpy + "\n        print(ID, x)", "x **= " + e.Python + "\n        print(ID, x)");
                        }
                    }
                }
            }
        }

        return cells;
    }

    /// <summary>
    /// CPython's <c>decimal.DivisionByZero</c> (a <c>ZeroDivisionError</c>) stringifies as its signal list, not a
    /// message; the Sharpy text for every division is the spec's "division by zero".
    /// </summary>
    private const string PythonPrelude =
        "import decimal\nfrom decimal import Decimal\n\n"
        + "def msg(e):\n    return \"division by zero\" if isinstance(e, decimal.DivisionByZero) else str(e)\n\n";

    private static string Join(string a, string b) => a.Length == 0 ? b : a + "\n        " + b;

    private static string Wrap(int id, string setup, string statement, string message)
    {
        var idText = id.ToString(CultureInfo.InvariantCulture);
        var sb = new StringBuilder();
        sb.Append("def cell_").Append(idText).Append("():\n");
        sb.Append("    try:\n");
        if (setup.Length > 0)
            sb.Append("        ").Append(setup).Append('\n');
        sb.Append("        ").Append(statement.Replace("ID", idText, StringComparison.Ordinal)).Append('\n');
        sb.Append("    except ZeroDivisionError as e:\n");
        sb.Append("        print(").Append(idText).Append(", \"ZeroDivisionError\", ").Append(message).Append(")\n");
        return sb.ToString();
    }

    private static string ProgramFor(IReadOnlyList<Cell> cells, Func<Cell, string> render, string prelude)
    {
        var sb = new StringBuilder(prelude);
        foreach (var c in cells)
            sb.Append(render(c)).Append('\n');
        sb.Append("def main():\n");
        foreach (var c in cells)
            sb.Append("    cell_").Append(c.Id.ToString(CultureInfo.InvariantCulture)).Append("()\n");
        return sb.ToString();
    }

    private static Dictionary<int, string> ParseLines(string stdout)
    {
        var byId = new Dictionary<int, string>();
        foreach (var raw in stdout.Split('\n'))
        {
            var line = raw.TrimEnd('\r');
            var space = line.IndexOf(' ');
            if (space > 0 && int.TryParse(line[..space], NumberStyles.Integer, CultureInfo.InvariantCulture, out var id))
                byId[id] = line[(space + 1)..];
        }
        return byId;
    }

    [SkippableFact]
    public void DivisionAndPowerByZero_OperatorTypeSpellingMatrix_MatchesCPython()
    {
        var oracle = PythonBatchOracle.Over(PythonInterpreter.RequireOrSkip(minMinor: 12));
        var cells = GenerateCells();

        var pythonSource = ProgramFor(cells, c => c.Python, PythonPrelude) + "\nmain()\n";
        var py = oracle.RunBatch(new[] { new PyRequest(0, pythonSource) });
        Assert.True(py.TryGetValue(0, out var pyResult) && pyResult.Ok,
            "python3 did not run the division matrix: " + (pyResult?.Stderr ?? "no verdict"));
        var pythonById = ParseLines(pyResult!.Stdout);
        Assert.Equal(cells.Count, pythonById.Count);

        var sharpySource = ProgramFor(cells, c => c.Sharpy, "");
        var run = CompileAndExecute(sharpySource, "zero_division_matrix.spy", executionTimeoutMs: 60_000);
        Assert.True(RanToCompletion(run), JudgeRun(run, sharpySource, "Sharpy division matrix") ?? "timed out");
        var sharpyById = ParseLines(run.StandardOutput);

        var divergences = new List<string>();
        foreach (var cell in cells)
        {
            var expected = pythonById[cell.Id];
            var actual = sharpyById.TryGetValue(cell.Id, out var s) ? s : "<no line>";
            if (!string.Equals(expected, actual, StringComparison.Ordinal))
                divergences.Add($"  #{cell.Id} {cell.Label}: python `{expected}`, sharpy `{actual}`");
        }

        // Positive controls: both messages and the non-raising arm are reached, and every operator family has a
        // raising cell, so the matrix cannot pass over a zero-free or an all-raising axis.
        Assert.Contains(cells, c => pythonById[c.Id] == "ZeroDivisionError division by zero");
        Assert.Contains(cells, c => pythonById[c.Id] == "ZeroDivisionError zero to a negative power");
        Assert.Contains(cells, c => !pythonById[c.Id].StartsWith("ZeroDivisionError", StringComparison.Ordinal));
        foreach (var op in new[] { " / ", " /= ", " ** ", " **= " })
            Assert.Contains(cells, c => c.Label.Contains(op, StringComparison.Ordinal)
                && pythonById[c.Id].StartsWith("ZeroDivisionError", StringComparison.Ordinal));

        Assert.True(divergences.Count == 0,
            $"{divergences.Count} of {cells.Count} division/power cells diverge from CPython:\n" + string.Join("\n", divergences));
    }
}
